import 'dart:convert';
import 'dart:typed_data';

/// A real 1x1 JPEG. Synthetic bytes between the SOI and EOI markers travel
/// through the frame splitter just as well, but `Image.memory` then fails to
/// decode them, so nothing proves a frame reached the screen.
Uint8List tinyJpeg() => base64Decode(_tinyJpeg);

const _tinyJpeg =
    '';
